class Employee{String name;int id;double salary;Employee(String n,int i,double s){name=n;id=i;salary=s;}double calculateSalary(){return salary;}}class Professor extends Employee{Professor(String n,int i,double s){super(n,i,s);}double calculateSalary(){return salary+5000;}}class LabAssistant extends Employee{LabAssistant(String n,int i,double s){super(n,i,s);}double calculateSalary(){return salary+2000;}}public class EmployeeInheritance{public static void main(String[] a){Employee[] e={new Professor("A",1,30000),new LabAssistant("B",2,20000)};for(Employee x:e)System.out.println(x.calculateSalary());}}